def build(a,extra):
    g=np.tanh(a*t)
    Ts=[np.ones_like(t),t,t**2,g,g*t,g*t**2] + ([g**2,g**2*t] if extra else [])
    return np.column_stack([T*Pk for T in Ts for Pk in Pp])
